WITH lines AS (SELECT id, plan, EXPLODE(tier_limits) AS element FROM price_tiers), kept_keys AS (SELECT id FROM lines INTERSECT ALL SELECT id FROM price_tiers WHERE YEAR(effective_from) >= 2023), reconciled AS (SELECT s.* FROM lines s INNER JOIN kept_keys k ON s.id = k.id), base AS (SELECT *, ROUND(element * 0.9, 2) AS adjusted_element FROM reconciled WHERE plan IN ('enterprise', 'basic', 'pro')) SELECT id, plan, CASE WHEN plan RLIKE '^(starter|pro)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS plan_zone FROM base ORDER BY id ASC NULLS FIRST
